INSERT INTO ai.translations (id, uuid, key, language, value, created_at, created_by, updated_at, updated_by, version, deleted_at, deleted_by) VALUES (621, '84babc55-a7f5-4126-a1f8-254fdbafea1c', 'ai.entities.ai_model.rank.explanation', 'it-IT', 'Punteggio composito: la qualità pesa 80%, la velocità pesa 20%. La qualità è la media dei punteggi per turno (5 turni); la velocità deriva dai tempi di risposta reali.', '2026-10-23 23:17:57.564706+00', 'migration-ai-pages-ownership', '2026-10-23 23:17:57.564706+00', 'migration-ai-pages-ownership', 1, NULL, NULL);
INSERT INTO ai.translations (id, uuid, key, language, value, created_at, created_by, updated_at, updated_by, version, deleted_at, deleted_by) VALUES (622, '6faa6ae7-95db-491a-9ff5-fec12cb6ade9', 'ai.entities.ai_model.rank.explanation', 'fr-FR', 'Score composite : la qualité pèse 80%, la vitesse 20%. La qualité est la moyenne des scores par tour (5 tours); la vitesse dérive des temps de réponse réels.', '2026-10-23 23:17:57.564706+00', 'migration-ai-pages-ownership', '2026-10-23 23:17:57.564706+00', 'migration-ai-pages-ownership', 1, NULL, NULL);
INSERT INTO ai.translations (id, uuid, key, language, value, created_at, created_by, updated_at, updated_by, version, deleted_at, deleted_by) VALUES (623, '649fb757-d6c6-4df2-8439-105cc87022c8', 'ai.entities.ai_model.rank.explanation', 'es-ES', 'Puntuación compuesta: la calidad pesa 80%, la velocidad 20%. La calidad es la media de los puntajes por turno (5 turnos); la velocidad deriva de los tiempos de respuesta reales.', '2026-10-23 23:17:57.564706+00', 'migration-ai-pages-ownership', '2026-10-23 23:17:57.564706+00', 'migration-ai-pages-ownership', 1, NULL, NULL);
INSERT INTO ai.translations (id, uuid, key, language, value, created_at, created_by, updated_at, updated_by, version, deleted_at, deleted_by) VALUES (624, 'd25c38b2-e0e7-4f40-846c-b78307fa6f0b', 'ai.entities.ai_model.rank.explanation', 'de-DE', 'Zusammengesetzte Punktzahl: Qualität gewichtet 80%, Geschwindigkeit 20%. Qualität ist der Mittelwert der Turn-Scores (5 Turns); Geschwindigkeit ergibt sich aus echten Antwortzeiten.', '2026-10-23 23:17:57.564706+00', 'migration-ai-pages-ownership', '2026-10-23 23:17:57.564706+00', 'migration-ai-pages-ownership', 1, NULL, NULL);
INSERT INTO ai.translations (id, uuid, key, language, value, created_at, created_by, updated_at, updated_by, version, deleted_at, deleted_by) VALUES (625, 'ced85926-aecb-4c69-9701-cd13e95cf0fd', 'ai.entities.ai_model.rank.explanation', 'pt-PT', 'Pontuação composta: a qualidade pesa 80%, a velocidade 20%. A qualidade é a média das pontuações por turno (5 turnos); a velocidade deriva dos tempos de resposta reais.', '2026-10-23 23:17:57.564706+00', 'migration-ai-pages-ownership', '2026-10-23 23:17:57.564706+00', 'migration-ai-pages-ownership', 1, NULL, NULL);
INSERT INTO ai.translations (id, uuid, key, language, value, created_at, created_by, updated_at, updated_by, version, deleted_at, deleted_by) VALUES (626, 'e60ff803-1d1a-4b6a-8301-8d4e9b95bc62', 'ai.entities.ai_model.power_level.explanation', 'en-GB', 'Measures model capacity from parameter count (1B, 2B, ...) and quantization — it reflects the weights only. A low value means limited capability; a high value means more capability but also more VRAM and compute, so a more powerful machine is required.', '2026-10-23 23:17:57.564706+00', 'migration-ai-pages-ownership', '2026-10-23 23:17:57.564706+00', 'migration-ai-pages-ownership', 1, NULL, NULL);
INSERT INTO ai.translations (id, uuid, key, language, value, created_at, created_by, updated_at, updated_by, version, deleted_at, deleted_by) VALUES (627, '1c24c33e-cce6-4d66-a629-01bf133ee931', 'ai.entities.ai_model.power_level.explanation', 'it-IT', 'Misura la capacità del modello in base ai parametri (1B, 2B, ...) e alla quantizzazione — riguarda solo i pesi. Un valore basso indica poca potenza, un valore alto molta potenza, ma più potenza richiede più VRAM e calcolo: serve una macchina più potente.', '2026-10-23 23:17:57.564706+00', 'migration-ai-pages-ownership', '2026-10-23 23:17:57.564706+00', 'migration-ai-pages-ownership', 1, NULL, NULL);
INSERT INTO ai.translations (id, uuid, key, language, value, created_at, created_by, updated_at, updated_by, version, deleted_at, deleted_by) VALUES (628, '4b0977a1-4260-433c-b891-28d04f86ff13', 'ai.entities.ai_model.power_level.explanation', 'fr-FR', 'Mesure la capacité du modèle selon le nombre de paramètres (1B, 2B, ...) et la quantification — uniquement les poids. Une valeur basse indique peu de puissance, une valeur élevée beaucoup de puissance, mais plus de puissance exige plus de VRAM et de calcul : il faut une machine plus puissante.', '2026-10-23 23:17:57.564706+00', 'migration-ai-pages-ownership', '2026-10-23 23:17:57.564706+00', 'migration-ai-pages-ownership', 1, NULL, NULL);
INSERT INTO ai.translations (id, uuid, key, language, value, created_at, created_by, updated_at, updated_by, version, deleted_at, deleted_by) VALUES (629, 'b313be5c-8838-48e5-9366-1bbeac9fb340', 'ai.entities.ai_model.power_level.explanation', 'es-ES', 'Mide la capacidad del modelo según el número de parámetros (1B, 2B, ...) y la cuantización — solo los pesos. Un valor bajo indica poca potencia, uno alto mucha potencia, pero más potencia requiere más VRAM y cómputo: se necesita una máquina más potente.', '2026-10-23 23:17:57.564706+00', 'migration-ai-pages-ownership', '2026-10-23 23:17:57.564706+00', 'migration-ai-pages-ownership', 1, NULL, NULL);
INSERT INTO ai.translations (id, uuid, key, language, value, created_at, created_by, updated_at, updated_by, version, deleted_at, deleted_by) VALUES (630, '0dcb9e17-b0d5-470b-b78f-1ff8dd926959', 'ai.entities.ai_model.power_level.explanation', 'de-DE', 'Misst die Modellkapazität anhand der Parameterzahl (1B, 2B, ...) und der Quantisierung — nur die Gewichte. Ein niedriger Wert bedeutet geringe Leistung, ein hoher Wert hohe Leistung, aber mehr Leistung erfordert mehr VRAM und Rechenleistung: ein leistungsstärkerer Rechner ist nötig.', '2026-10-23 23:17:57.564706+00', 'migration-ai-pages-ownership', '2026-10-23 23:17:57.564706+00', 'migration-ai-pages-ownership', 1, NULL, NULL);
INSERT INTO ai.translations (id, uuid, key, language, value, created_at, created_by, updated_at, updated_by, version, deleted_at, deleted_by) VALUES (631, 'e41d87aa-50fb-4e8b-bf66-ce7cf050e291', 'ai.entities.ai_model.power_level.explanation', 'pt-PT', 'Mede a capacidade do modelo com base no número de parâmetros (1B, 2B, ...) e na quantização — apenas os pesos. Um valor baixo indica pouca potência, um valor alto muita potência, mas mais potência exige mais VRAM e computação: é preciso uma máquina mais potente.', '2026-10-23 23:17:57.564706+00', 'migration-ai-pages-ownership', '2026-10-23 23:17:57.564706+00', 'migration-ai-pages-ownership', 1, NULL, NULL);
INSERT INTO ai.translations (id, uuid, key, language, value, created_at, created_by, updated_at, updated_by, version, deleted_at, deleted_by) VALUES (632, 'd0264cab-df37-4862-8bf7-aafa6f543a0a', 'ai.entities.ai_model.power_level.disclaimer', 'en-GB', 'The synthetic value for the real overall power of the model is Rank (Classifica).', '2026-10-23 23:17:57.564706+00', 'migration-ai-pages-ownership', '2026-10-23 23:17:57.564706+00', 'migration-ai-pages-ownership', 1, NULL, NULL);
